// Get basic input parameters
const sessionId = $('Prepare Input').item.json.sessionId;
const framework  = $('Prepare Input').item.json.framework;

// Compatible with model placing results at root or output layer
const out = $json.output ? $json.output : $json;

const finalQuestion = String(out.final_question || '').trim();
const components    = (out.components && typeof out.components === 'object') ? out.components : {};

// Uniformly store in database: store final question + selected framework + framework components together in final_structured_memory
const fsm = {
  framework,                // User-selected framework
  final_question: finalQuestion,
  components                // All component key-values used for frontend backfilling/organization
};

// As input for next SQL step
return [{
  json: {
    session_id: sessionId,
    classified_framework: framework,
    fsm_str: JSON.stringify(fsm),    // ::jsonb for database
    final_question: finalQuestion    // Can also be returned to frontend
  }
}];

