const src = $json;

const rawText = (typeof src === 'string')
  ? src
  : (src.text ?? src.message ?? src.output ?? src.content ?? JSON.stringify(src));

function tryParse(s) {
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

function stripFences(s) {
  return String(s || '')
    .replace(/^\s*```(?:json)?/i, '')
    .replace(/```?\s*$/i, '')
    .trim();
}

function extractFirstJSON(s) {
  if (!s) return null;

  let obj = tryParse(s);
  if (obj && typeof obj === 'object') return obj;

  const cleaned = stripFences(s);
  obj = tryParse(cleaned);
  if (obj && typeof obj === 'object') return obj;

  let start = cleaned.indexOf('{');
  while (start !== -1) {
    let depth = 0;
    let inStr = false;
    let prev = '';

    for (let i = start; i < cleaned.length; i++) {
      const ch = cleaned[i];

      if (ch === '"' && prev !== '\\') {
        inStr = !inStr;
      } else if (!inStr) {
        if (ch === '{') depth++;
        else if (ch === '}') {
          depth--;
          if (depth === 0) {
            const cand = cleaned.slice(start, i + 1);
            obj = tryParse(cand);
            if (obj && typeof obj === 'object') return obj;
            break;
          }
        }
      }

      prev = ch;
    }

    start = cleaned.indexOf('{', start + 1);
  }

  return null;
}

const framework = $('Prepare Input').item.json.framework;
const frameworkData = $('Prepare Input').item.json.frameworkData;

let parsed = extractFirstJSON(rawText);

if (parsed && typeof parsed.components === 'string') {
  const inner = tryParse(parsed.components);
  if (inner && typeof inner === 'object') {
    parsed.components = inner;
  }
}

// If parsing completely fails, provide a minimal empty skeleton
if (!parsed || typeof parsed !== 'object') {
  parsed = { final_question: '', components: {} };
}

parsed.final_question = String(parsed.final_question || '').trim();
if (!parsed.components || typeof parsed.components !== 'object') {
  parsed.components = {};
}

function rebuildFinalQuestion(fr, comp) {
  if (fr === 'PECO') {
    const P = comp.P || '';
    const E = comp.E || '';
    const C = comp.C || '';
    const O = comp.O || '';
    return `[PECO] Among ${P}, compare ${E} versus ${C}, to assess whether associated with prevalence of ${O}?`.trim();
  }

  if (fr === 'CoCoPop') {
    const Context = comp.Context || '';
    const Pop = comp.Pop || '';
    const Co = comp.Co || '';
    return `[CoCoPop] In ${Context}, what is the prevalence of ${Co} among ${Pop}?`.trim();
  }

  if (fr === 'SPIDER') {
    const S = comp.S || '';
    const PI = comp.PI || '';
    const D = comp.D || '';
    const E = comp.E || '';
    const R = comp.R || '';
    return `[SPIDER] This ${R} study will, based on ${D}, explore ${PI} among ${S} and conduct ${E}.`.trim();
  }

  if (fr === 'PECO和CoCoPop') {
    const co = comp.CoCoPop || {};
    const pe = comp.PECO || {};
    const line1 = `[CoCoPop] In ${co.Context || ''}, what is the prevalence of ${co.Co || ''} among ${co.Pop || ''}?`;
    const line2 = `[PECO] Among ${pe.P || ''}, compare ${pe.E || ''} versus ${pe.C || ''}, to assess whether associated with prevalence of ${pe.O || ''}?`;
    return `${line1}\n${line2}`.trim();
  }

  return parsed.final_question;
}

parsed.final_question = rebuildFinalQuestion(framework, parsed.components);

return [{ json: parsed }];
